FunctionalRequirement FR-044 {"label": "Tạm dừng và tiếp tục lịch định kỳ", "version": "0.1", "status": "InReview", "sourceDoc": "SRS", "sourceSection": "Yêu cầu chức năng", "text": "Tạm dừng và tiếp tục lịch định kỳ", "priority": "Should"}
FunctionalRequirement FR-045 {"label": "Đến hạn, tự chuyển tiền bằng luồng chuyển tiền hiện có; Idempotency-Key = mã lịch + thời điểm dự kiến", "version": "0.1", "status": "InReview", "sourceDoc": "SRS", "sourceSection": "Yêu cầu chức năng", "text": "Đến hạn, tự chuyển tiền bằng luồng chuyển tiền hiện có; Idempotency-Key = mã lịch + thời điểm dự kiến", "priority": "Must"}
FunctionalRequirement FR-046 {"label": "Xử lý thất bại của lần chạy theo loại lỗi (BR-13): thử lại, FAILED, tự PAUSED sau 3 lần FAILED liên tiếp", "version": "0.1", "status": "InReview", "sourceDoc": "SRS", "sourceSection": "Yêu cầu chức năng", "text": "Xử lý thất bại của lần chạy theo loại lỗi (BR-13): thử lại, FAILED, tự PAUSED sau 3 lần FAILED liên tiếp", "priority": "Must"}
FunctionalRequirement FR-047 {"label": "Thông báo kết quả mỗi lần chạy qua SMS (ScheduledRunCompleted/ScheduledRunFailed qua outbox)", "version": "0.1", "status": "InReview", "sourceDoc": "SRS", "sourceSection": "Yêu cầu chức năng", "text": "Thông báo kết quả mỗi lần chạy qua SMS (ScheduledRunCompleted/ScheduledRunFailed qua outbox)", "priority": "Should"}
