FunctionalRequirement FR-049 {"label": "Chạy bù các lần chạy quá hạn không quá 24 giờ sau khi hệ thống ngừng; quá hạn thì MISSED", "version": "0.1", "status": "InReview", "sourceDoc": "SRS", "sourceSection": "Yêu cầu chức năng", "text": "Chạy bù các lần chạy quá hạn không quá 24 giờ sau khi hệ thống ngừng; quá hạn thì MISSED", "priority": "Should"}
NonFunctionalRequirement NFR-010 {"label": "Đúng giờ: 99% lần chạy bắt đầu trong 60 giây kể từ thời điểm dự kiến", "version": "0.1", "status": "InReview", "sourceDoc": "SRS", "sourceSection": "Yêu cầu phi chức năng", "text": "Đúng giờ: 99% lần chạy bắt đầu trong 60 giây kể từ thời điểm dự kiến", "priority": "Must", "targetValue": 60, "targetUnit": "s"}
NonFunctionalRequirement NFR-011 {"label": "Không chạy trùng: 0 giao dịch trùng cho một lần chạy, kể cả khi hai scheduler cùng quét", "version": "0.1", "status": "InReview", "sourceDoc": "SRS", "sourceSection": "Yêu cầu phi chức năng", "text": "Không chạy trùng: 0 giao dịch trùng cho một lần chạy, kể cả khi hai scheduler cùng quét", "priority": "Must", "targetValue": 0, "targetUnit": "giao dịch trùng"}
NonFunctionalRequirement NFR-012 {"label": "Phục hồi: sau khởi động lại, lần chạy quá hạn trong 24 giờ được xử lý trong 5 chu kỳ quét đầu", "version": "0.1", "status": "InReview", "sourceDoc": "SRS", "sourceSection": "Yêu cầu phi chức năng", "text": "Phục hồi: sau khởi động lại, lần chạy quá hạn trong 24 giờ được xử lý trong 5 chu kỳ quét đầu", "priority": "Must", "targetValue": 5, "targetUnit": "chu kỳ quét"}
