"""Business logic: MOD-Account, MOD-Transfer, MOD-Ledger, MOD-Risk glue, MOD-Audit."""
import hashlib
import json
import random
import secrets
import uuid
from datetime import datetime, timedelta, timezone
from . import config as C
from .db import tx
from .errors import err
from .fraud_client import FraudUnavailable

now = lambda: datetime.now(timezone.utc).isoformat()


def _hash(s: str) -> str:
    return hashlib.sha256(s.encode()).hexdigest()


def audit(con, event_type, actor=None, cid=None, reason=None, ref_id=None):
    con.execute("INSERT INTO audit_logs(event_type,actor,correlation_id,reason,ref_id,created_at)"
                " VALUES(?,?,?,?,?,?)", (event_type, actor, cid, reason, ref_id, now()))


# ---- MOD-Account ------------------------------------------------------
def create_account(con, owner: str, phone: str | None, cid: str) -> dict:
    if not owner or not owner.strip():
        raise err("INVALID_REQUEST", "owner required")
    api_key = "mp_" + secrets.token_urlsafe(24)
    with tx(con):
        while True:
            acc_id = "".join(random.choice("0123456789") for _ in range(10))
            if not con.execute("SELECT 1 FROM accounts WHERE id=?", (acc_id,)).fetchone():
                break
        con.execute("INSERT INTO accounts VALUES(?,?,?,?,?,?)",
                    (acc_id, owner.strip(), phone, "ACTIVE", _hash(api_key), now()))
        audit(con, "ACCOUNT_CREATED", acc_id, cid, ref_id=acc_id)
    return {"accountId": acc_id, "apiKey": api_key, "status": "ACTIVE", "balance": 0}


def authenticate(con, api_key: str | None) -> str:
    if not api_key:
        raise err("UNAUTHORIZED")
    row = con.execute("SELECT id FROM accounts WHERE api_key_hash=?", (_hash(api_key),)).fetchone()
    if not row:
        raise err("UNAUTHORIZED")
    return row["id"]


def balance_of(con, acc_id: str) -> int:
    row = con.execute("SELECT balance_after FROM ledger_entries WHERE account_id=? ORDER BY id DESC LIMIT 1",
                      (acc_id,)).fetchone()
    return row["balance_after"] if row else 0


def get_account(con, acc_id: str, caller: str) -> dict:
    if acc_id != caller:
        raise err("FORBIDDEN")
    a = con.execute("SELECT * FROM accounts WHERE id=?", (acc_id,)).fetchone()
    if not a:
        raise err("ACCOUNT_NOT_FOUND")
    return {"accountId": a["id"], "owner": a["owner"], "status": a["status"],
            "balance": balance_of(con, acc_id), "createdAt": a["created_at"]}


def deposit(con, acc_id: str, amount, caller: str, cid: str) -> dict:
    if acc_id != caller:
        raise err("FORBIDDEN")
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        raise err("INVALID_REQUEST", "amount must be a positive integer (VND)")
    with tx(con):
        a = con.execute("SELECT status FROM accounts WHERE id=?", (acc_id,)).fetchone()
        if not a:
            raise err("ACCOUNT_NOT_FOUND")
        if a["status"] != "ACTIVE":
            raise err("ACCOUNT_INACTIVE")
        bal = balance_of(con, acc_id) + amount
        con.execute("INSERT INTO ledger_entries(account_id,transfer_id,direction,amount,balance_after,kind,created_at)"
                    " VALUES(?,?,?,?,?,?,?)", (acc_id, None, "CREDIT", amount, bal, "DEPOSIT", now()))
        audit(con, "DEPOSIT", acc_id, cid, ref_id=acc_id)
    return {"accountId": acc_id, "balance": bal}


# ---- MOD-Transfer -----------------------------------------------------
def _day_start_utc() -> str:
    tz = timezone(timedelta(hours=C.TZ_OFFSET_HOURS))
    d = datetime.now(tz).replace(hour=0, minute=0, second=0, microsecond=0)
    return d.astimezone(timezone.utc).isoformat()


def _view(t) -> dict:
    d = {"transferId": t["id"], "fromAccountId": t["from_account"], "toAccountId": t["to_account"],
         "amount": t["amount"], "status": t["status"], "reasonCode": t["reason_code"],
         "riskCheck": t["risk_check"], "createdAt": t["created_at"], "correlationId": t["correlation_id"]}
    return d


def _stored_error(t):
    """Replay of a stored REJECTED transfer returns the same error (FR-012)."""
    code = t["reason_code"]
    from .errors import ERRORS
    return err(code, f"transfer {t['id']} was rejected: {code}") if code in ERRORS else None


def transfer(con, caller: str, body: dict, idem_key: str | None, cid: str, fraud) -> tuple[dict, bool]:
    """Returns (transfer view, replayed). Raises MiniPayError."""
    # 1. validate (BR-01)
    if not idem_key:
        raise err("INVALID_REQUEST", "Idempotency-Key header required")
    frm, to, amt = body.get("fromAccountId"), body.get("toAccountId"), body.get("amount")
    if not frm or not to or not isinstance(amt, int) or isinstance(amt, bool) or amt <= 0:
        raise err("INVALID_REQUEST", "fromAccountId, toAccountId, positive integer amount required")
    if frm != caller:
        raise err("FORBIDDEN")
    req_hash = _hash(json.dumps([frm, to, amt, body.get("note")], sort_keys=True))
    # 2. idempotency (FR-012)
    prev = con.execute("SELECT * FROM transfers WHERE from_account=? AND idempotency_key=?",
                       (frm, idem_key)).fetchone()
    if prev:
        if prev["request_hash"] != req_hash:
            raise err("IDEMPOTENCY_CONFLICT")
        e = _stored_error(prev) if prev["status"] == "REJECTED" else None
        if e:
            raise e
        return _view(prev), True
    if frm == to:
        raise err("SAME_ACCOUNT")
    rows = {r["id"]: r for r in con.execute("SELECT * FROM accounts WHERE id IN (?,?)", (frm, to))}
    if frm not in rows or to not in rows:
        raise err("ACCOUNT_NOT_FOUND")
    tid = "TRF-" + uuid.uuid4().hex[:12].upper()

    def reject(code: str, risk_check=None, score=None):
        with tx(con):
            con.execute("INSERT INTO transfers VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (tid, frm, to, amt, body.get("note"), "REJECTED", code, risk_check, score,
                         idem_key, req_hash, cid, now()))
            audit(con, "TRANSFER_REJECTED", frm, cid, code, tid)
        raise err(code)

    if rows[frm]["status"] != "ACTIVE" or rows[to]["status"] != "ACTIVE":
        reject("ACCOUNT_INACTIVE")
    # 3. limits & balance pre-check (FR-011, BR-04, BR-05)
    def limit_or_balance(c):
        if amt > C.MAX_PER_TRANSFER:
            return "LIMIT_EXCEEDED"
        used = c.execute("SELECT COALESCE(SUM(amount),0) s FROM transfers WHERE from_account=? "
                         "AND status='COMPLETED' AND created_at>=?", (frm, _day_start_utc())).fetchone()["s"]
        if used + amt > C.MAX_PER_DAY:
            return "LIMIT_EXCEEDED"
        if balance_of(c, frm) < amt:
            return "INSUFFICIENT_FUNDS"
        return None
    code = limit_or_balance(con)
    if code:
        reject(code)
    # 4. fraud check OUTSIDE the DB transaction (NFR-006)
    risk_check, score = "APPROVED", None
    try:
        res = fraud.check(cid, tid, frm, to, amt)
        score = res["riskScore"]
        if res["decision"] == "REJECT":
            reject("FRAUD_REJECTED", "REJECTED", score)
    except FraudUnavailable:
        if amt >= C.FRAUD_FAIL_THRESHOLD:           # FR-020 / BR-06
            reject("FRAUD_CHECK_UNAVAILABLE", "UNAVAILABLE")
        risk_check = "SKIPPED"
    # 5. atomic booking (FR-010, AP-02, AP-04)
    with tx(con):
        code = limit_or_balance(con)                # re-check under write lock
        if code:
            con.execute("INSERT INTO transfers VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (tid, frm, to, amt, body.get("note"), "REJECTED", code, risk_check, score,
                         idem_key, req_hash, cid, now()))
            audit(con, "TRANSFER_REJECTED", frm, cid, code, tid)
            con.execute("COMMIT"); con.execute("BEGIN IMMEDIATE")   # persist rejection, then surface
            raise err(code)
        con.execute("INSERT INTO transfers VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (tid, frm, to, amt, body.get("note"), "COMPLETED", None, risk_check, score,
                     idem_key, req_hash, cid, now()))
        b_from = balance_of(con, frm) - amt
        b_to = balance_of(con, to) + amt
        con.execute("INSERT INTO ledger_entries(account_id,transfer_id,direction,amount,balance_after,kind,created_at)"
                    " VALUES(?,?,?,?,?,?,?)", (frm, tid, "DEBIT", amt, b_from, "TRANSFER", now()))
        con.execute("INSERT INTO ledger_entries(account_id,transfer_id,direction,amount,balance_after,kind,created_at)"
                    " VALUES(?,?,?,?,?,?,?)", (to, tid, "CREDIT", amt, b_to, "TRANSFER", now()))
        con.execute("INSERT INTO outbox_events(event_type,payload,created_at) VALUES(?,?,?)",
                    ("TransferCompleted", json.dumps({"eventId": tid, "transferId": tid, "fromAccountId": frm,
                     "toAccountId": to, "amount": amt, "correlationId": cid}), now()))
        audit(con, "TRANSFER_COMPLETED", frm, cid, ref_id=tid)
    return _view(con.execute("SELECT * FROM transfers WHERE id=?", (tid,)).fetchone()), False


def get_transfer(con, tid: str, caller: str) -> dict:
    t = con.execute("SELECT * FROM transfers WHERE id=?", (tid,)).fetchone()
    if not t:
        raise err("ACCOUNT_NOT_FOUND", "transfer not found")
    if caller not in (t["from_account"], t["to_account"]):
        raise err("FORBIDDEN")
    return _view(t)


def history(con, acc_id: str, caller: str, limit: int = 20, offset: int = 0) -> list[dict]:
    if acc_id != caller:
        raise err("FORBIDDEN")
    limit = max(1, min(limit, 100))
    rows = con.execute("SELECT * FROM transfers WHERE from_account=? OR to_account=? "
                       "ORDER BY created_at DESC LIMIT ? OFFSET ?", (acc_id, acc_id, limit, offset)).fetchall()
    return [_view(r) for r in rows]
"""INT-01 Fraud Check client (adapter, MOD-Risk). Implements the TDD contract:
POST /v1/fraud/checks, headers X-Correlation-Id + Authorization, timeouts,
connection pool, 1 retry, circuit breaker."""
import threading
import time
import httpx
from . import config as C


class FraudUnavailable(Exception):
    pass


class FraudClient:
    def __init__(self, base_url: str = C.FRAUD_URL, transport: httpx.BaseTransport | None = None,
                 api_token: str = "demo-fraud-token"):
        self._client = httpx.Client(
            base_url=base_url, transport=transport,
            timeout=httpx.Timeout(C.FRAUD_TOTAL_TIMEOUT_S, connect=C.FRAUD_CONNECT_TIMEOUT_S,
                                  read=C.FRAUD_READ_TIMEOUT_S),
            limits=httpx.Limits(max_connections=C.FRAUD_POOL_MAX_CONNECTIONS,
                                max_keepalive_connections=C.FRAUD_POOL_MAX_KEEPALIVE,
                                keepalive_expiry=C.FRAUD_POOL_IDLE_TIMEOUT_S),
            headers={"Authorization": f"Bearer {api_token}"})
        self._lock = threading.Lock()
        self._failures = 0
        self._open_until = 0.0

    # circuit breaker --------------------------------------------------
    def _is_open(self) -> bool:
        with self._lock:
            return time.monotonic() < self._open_until

    def _record(self, ok: bool) -> None:
        with self._lock:
            if ok:
                self._failures = 0
                return
            self._failures += 1
            if self._failures >= C.FRAUD_BREAKER_FAILURE_THRESHOLD:
                self._open_until = time.monotonic() + C.FRAUD_BREAKER_OPEN_SECONDS
                self._failures = 0

    def check(self, correlation_id: str, transfer_id: str, from_account: str,
              to_account: str, amount: int) -> dict:
        if self._is_open():
            raise FraudUnavailable("circuit open")
        body = {"transactionId": transfer_id, "fromAccount": from_account,
                "toAccount": to_account, "amount": amount, "currency": "VND"}
        last: Exception | None = None
        for _ in range(1 + C.FRAUD_MAX_RETRIES):
            try:
                r = self._client.post("/v1/fraud/checks", json=body,
                                      headers={"X-Correlation-Id": correlation_id})
                if r.status_code >= 500:
                    last = FraudUnavailable(f"HTTP {r.status_code}")
                    continue
                if r.status_code != 200:   # 4xx: contract violation, no retry
                    self._record(False)
                    raise FraudUnavailable(f"HTTP {r.status_code}")
                data = r.json()
                if data.get("decision") not in ("APPROVE", "REJECT"):
                    self._record(False)
                    raise FraudUnavailable("invalid response schema")
                self._record(True)
                return {"decision": data["decision"], "riskScore": int(data.get("riskScore", 0))}
            except httpx.TransportError as e:   # timeout / connect error
                last = FraudUnavailable(type(e).__name__)
        self._record(False)
        raise last or FraudUnavailable("unknown")

    def close(self):
        self._client.close()
